INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"b52410b6-cd4b-5b46-b9b9-210f98342eb6","title":"Mathematics · Grade 12 · Term 2: Geometry and differential calculus · Set A","subject":"Mathematics","grade":"Grade 12","questions":[{"question":"Find the gradient of the tangent to f(x) = x³ − 2x at x = 2.","options":["6","4","12","10"],"correct_index":3,"explanation":"Differentiate first: f′(x)=3x²−2. Then f′(2)=12−2=10. f(2)=4 is the function value, not the gradient.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A tangent touches a circle at A. What angle does it make with the radius to A?","options":["90°","45°","180°","60°"],"correct_index":0,"explanation":"A radius drawn to a point of tangency is perpendicular to the tangent. Include the point-of-contact condition when citing the theorem.","cognitive_level":{"code":"L1","label":"Knowledge","band":"lower"}},{"question":"Find the equation of a circle with centre (2; −1) and radius 3.","options":["(x+2)²+(y−1)²=9","(x−2)²+(y+1)²=9","(x−2)²+(y+1)²=3","x²+y²=9"],"correct_index":1,"explanation":"Use (x−a)²+(y−b)²=r². Here b=−1, so y−b becomes y+1, and r²=9.","cognitive_level":{"code":"L1","label":"Knowledge","band":"lower"}},{"question":"For f(x) = x² − 4x, where is the stationary point?","options":["x = 4","x = 0","x = 2","x = −2"],"correct_index":2,"explanation":"At a stationary point f′(x)=0. Since f′(x)=2x−4, solve 2x−4=0 to get x=2.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"An open rectangular pen is built against a wall with 20 m of fencing for its other three sides. Which dimensions maximise its area?","options":["10 m perpendicular and 0 m along it","4 m perpendicular and 12 m along it","5 m perpendicular to the wall and 10 m along it","6 m perpendicular and 8 m along it"],"correct_index":2,"explanation":"With width x, length is 20−2x and area 20x−2x². Its derivative 20−4x vanishes at x=5; the negative second derivative confirms a maximum of 50 m².","cognitive_level":{"code":"L4","label":"Problem solving","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Geometry and differential calculus. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","math"],"metadata":{"term":2,"focus":"Geometry and differential calculus","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_kS5tgxXQ0I%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge","Routine procedures","Complex procedures","Problem solving"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"0b73d5d1-406f-5080-a6cf-2f2f0ccc08cd","title":"Mathematics · Grade 12 · Term 3: Finance, regression and counting · Set A","subject":"Mathematics","grade":"Grade 12","questions":[{"question":"R5 000 grows at 10% per year compounded annually. Its value after 2 years is…","options":["R6 050","R6 000","R5 500","R7 000"],"correct_index":0,"explanation":"A=P(1+i)ⁿ = 5 000(1.10)² = 6 050. Compound interest includes interest on the first year's interest.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A regression model is ŷ = 2x + 5. Predict y when x = 4.","options":["11","13","8","18"],"correct_index":1,"explanation":"Substitute x=4: ŷ=2(4)+5=13. This is a model prediction, not a guaranteed observed value.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"How many 3-digit codes can be formed from 0–9 if repetition is allowed and a code may start with 0?","options":["900","720","1 000","30"],"correct_index":2,"explanation":"Each of three positions has 10 choices. Multiply 10×10×10. A code differs from a three-digit number because leading zero is allowed.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A test for a condition has P(positive and condition)=0.18 and P(positive)=0.30. Find P(condition given positive).","options":["0.054","0.48","0.12","0.60"],"correct_index":3,"explanation":"Conditional probability divides the intersection by the conditioning event: 0.18/0.30 = 0.60.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A regression fitted only to ages 12–18 predicts a person's height at age 80. Why should that prediction be treated cautiously?","options":["A fitted line guarantees accurate predictions at every age.","The slope proves age is the only cause of height.","It extrapolates far beyond the observed ages, where the relationship may change.","Regression cannot describe any association."],"correct_index":2,"explanation":"The model's observed age range is limited. A linear growth pattern during adolescence need not continue in adulthood, so substituting 80 does not validate the prediction.","cognitive_level":{"code":"L3","label":"Complex procedures","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Finance, regression and counting. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","math"],"metadata":{"term":3,"focus":"Finance, regression and counting","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_kS5tgxXQ0I%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge","Routine procedures","Complex procedures","Problem solving"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"08bee9f1-103d-5c8a-85c1-2b225b50bcc1","title":"Mathematics · Grade 12 · Term 4: Integrated examination revision · Set A","subject":"Mathematics","grade":"Grade 12","questions":[{"question":"The first three terms of an arithmetic sequence are 7, 11, 15. Find term 20.","options":["80","83","87","77"],"correct_index":1,"explanation":"Tₙ=a+(n−1)d = 7+19×4 = 83. There are 19 increases from term 1 to term 20.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Find the derivative of f(x) = 2x³ − 5x² + 4.","options":["6x² − 5x","2x² − 10x + 4","6x² − 10x","6x³ − 10x²"],"correct_index":2,"explanation":"Apply the power rule term by term. A constant's derivative is zero; the exponent decreases by one.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"For x² − 4x + 3 = 0, what is the discriminant?","options":["28","−4","16","4"],"correct_index":3,"explanation":"Δ=b²−4ac = (−4)²−4(1)(3)=4. It is positive, so the quadratic has two distinct real roots.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A circle has diameter AB with A(−2; 0), B(4; 0). Find its radius.","options":["3","6","1","9"],"correct_index":0,"explanation":"Diameter length = 4−(−2)=6, so radius is half: 3. The centre is (1;0), but its x-coordinate is not the radius.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A quadratic sequence has T₁=2, T₂=6 and T₃=12, with constant second difference 2. Which term is the first greater than 100?","options":["T₉=90","T₁₁=132","T₁₀=110","T₁₂=156"],"correct_index":2,"explanation":"The sequence is Tₙ=n²+n. Solve n(n+1)>100 for positive integers: T₉=90 and T₁₀=110. Although later terms also exceed 100, the first is term 10.","cognitive_level":{"code":"L3","label":"Complex procedures","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Integrated examination revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","math"],"metadata":{"term":4,"focus":"Integrated examination revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_kS5tgxXQ0I%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge","Routine procedures","Complex procedures","Problem solving"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"e67af533-d4ef-5d48-91d2-7177d1968328","title":"Mathematical Literacy · Grade 12 · Term 2: Measurement, scale and route planning · Set A","subject":"Mathematical Literacy","grade":"Grade 12","questions":[{"question":"A rectangular floor is 6 m × 4 m. Tiles cover 0.25 m² each. Ignoring waste, how many tiles are needed?","options":["96","24","48","6"],"correct_index":0,"explanation":"Floor area = 24 m². Divide by area per tile: 24/0.25 = 96. The units cancel to a count.","cognitive_level":{"code":"L3","label":"Applying multi-step procedures","band":"middle"}},{"question":"A map distance of 7.5 cm represents 15 km. What is the map scale?","options":["1:2 000","1:200 000","1:20 000","1:2 000 000"],"correct_index":1,"explanation":"15 km = 1 500 000 cm. Divide both lengths by 7.5 to obtain 1:200 000.","cognitive_level":{"code":"L3","label":"Applying multi-step procedures","band":"middle"}},{"question":"A cylindrical tank has radius 1 m and height 2 m. Using π = 3.14, find its capacity.","options":["628 L","62 800 L","6 280 L","3 140 L"],"correct_index":2,"explanation":"V=πr²h = 6.28 m³. Multiply by 1 000 to convert cubic metres into litres.","cognitive_level":{"code":"L3","label":"Applying multi-step procedures","band":"middle"}},{"question":"A bus leaves at 22:45 and arrives next day at 05:15. Find the journey time.","options":["17 h 30 min","7 h 30 min","5 h 30 min","6 h 30 min"],"correct_index":3,"explanation":"From 22:45 to midnight is 1 h 15 min, then another 5 h 15 min. Add to get 6 h 30 min.","cognitive_level":{"code":"L3","label":"Applying multi-step procedures","band":"middle"}},{"question":"A 24 m² floor needs 0.25 m² tiles. Add 10% to the tile count for waste; tiles come in packs of 10. How many packs must be bought?","options":["10 packs","9 packs","11 packs","12 packs"],"correct_index":2,"explanation":"The basic count is 24÷0.25=96. With waste it is 105.6, requiring at least 106 tiles. Ten packs give only 100; eleven packs provide 110.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Measurement, scale and route planning. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","matlit"],"metadata":{"term":2,"focus":"Measurement, scale and route planning","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=X4ZvlGUQ0vY%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing","Applying routine procedures","Applying multi-step procedures","Reasoning and reflecting"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"467737bb-9cd5-5bb2-94dc-a0bb5d82c87d","title":"Mathematical Literacy · Grade 12 · Term 3: Plans, packaging and integrated practice · Set A","subject":"Mathematical Literacy","grade":"Grade 12","questions":[{"question":"A floor plan uses 1:50. A door is 1.8 cm wide on the plan. Find the real width.","options":["9 m","0.9 m","0.09 m","90 m"],"correct_index":1,"explanation":"Multiply 1.8 cm by 50 = 90 cm = 0.9 m. Retain the same units until after scaling.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A carton holds 4 rows of 6 cans in one layer and has 3 layers. How many cans fit?","options":["24","18","72","48"],"correct_index":2,"explanation":"Multiply rows × cans per row × layers: 4×6×3 = 72. Counting only one layer gives 24.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A rectangular parcel is 40 cm × 30 cm × 20 cm. Find its volume.","options":["2 400 cm³","5 200 cm³","90 cm³","24 000 cm³"],"correct_index":3,"explanation":"Multiply all three dimensions: 40×30×20 = 24 000 cm³. Adding lengths does not calculate volume.","cognitive_level":{"code":"L3","label":"Applying multi-step procedures","band":"middle"}},{"question":"A delivery contract charges R250 plus R8 per kilometre. Find the cost for 35 km.","options":["R530","R280","R285","R8 750"],"correct_index":0,"explanation":"The distance cost is 8×35 = R280. Add the fixed R250 once: R530.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"Contract A charges R250+R8/km; B charges R100+R12/km. A driver says B is always cheaper because its fixed charge is lower. What happens at 50 km?","options":["B costs R700 and is R50 cheaper than A.","Both cost R650.","A costs R650 and is R50 cheaper than B.","A costs R400 because the fixed charge is ignored."],"correct_index":2,"explanation":"A=250+8×50=R650. B=100+12×50=R700. A smaller fixed charge need not produce a smaller total once the distance charge is considered.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Plans, packaging and integrated practice. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","matlit"],"metadata":{"term":3,"focus":"Plans, packaging and integrated practice","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=X4ZvlGUQ0vY%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing","Applying routine procedures","Applying multi-step procedures","Reasoning and reflecting"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"63c3dd89-26b5-54ff-8c57-369d252da46a","title":"Mathematical Literacy · Grade 12 · Term 4: Exam revision: finance, data and probability · Set A","subject":"Mathematical Literacy","grade":"Grade 12","questions":[{"question":"For this exercise, a price of R1 150 includes 15% VAT. Find the price before VAT.","options":["R977.50","R1 135","R1 000","R1 322.50"],"correct_index":2,"explanation":"The inclusive price is 115% of the base. Divide R1 150 by 1.15. Subtracting 15% of R1 150 uses the wrong base.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A salary rises from R8 000 to R8 600. Find the percentage increase.","options":["6.98%","75%","0.075%","7.5%"],"correct_index":3,"explanation":"Increase = R600. Divide by original salary: 600/8 000×100 = 7.5%.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A group has 12 learners; 7 are girls. One learner is selected fairly. P(not a girl) = ?","options":["5/12","7/12","5/7","1/12"],"correct_index":0,"explanation":"There are 12−7=5 learners who are not girls. Use 5 favourable outcomes out of 12.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A scatter plot shows that electricity use tends to rise with household size. What does this establish?","options":["That every large household uses more than every small one","An association, not proof that size alone causes usage","That electricity use causes more household members","That other factors have no effect"],"correct_index":1,"explanation":"A trend describes association. Appliances, weather, income and behaviour can also affect use; correlation alone does not establish causation.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}},{"question":"An item costs R1 150 including 15% VAT. A shop removes VAT by deducting 15% of R1 150. Which judgement is correct?","options":["The method is correct and gives R977.50 before VAT.","Add 15% again to reverse VAT.","The method is wrong: divide by 1.15 to obtain R1 000.","The original price cannot be found from the information."],"correct_index":2,"explanation":"The inclusive amount represents 115% of the pre-VAT base. Subtracting 15% of the inclusive amount uses a larger base than the original VAT calculation.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Exam revision: finance, data and probability. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","matlit"],"metadata":{"term":4,"focus":"Exam revision: finance, data and probability","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=X4ZvlGUQ0vY%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing","Applying routine procedures","Applying multi-step procedures","Reasoning and reflecting"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"b64e5c91-c380-540f-9f87-466ddcf22671","title":"Physical Sciences · Grade 12 · Term 2: Work, Doppler effect and equilibrium · Set A","subject":"Physical Sciences","grade":"Grade 12","questions":[{"question":"A constant 20 N force acts parallel to a 3 m displacement. Find the work done by this force.","options":["6.67 J","60 J","23 J","0 J"],"correct_index":1,"explanation":"W=FΔx cosθ. Here θ=0°, so cosθ=1 and W=20×3=60 J. Only the parallel component does work.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"An ambulance approaches a stationary observer. Compared with the emitted sound, the observed frequency is…","options":["Lower","Always zero","Higher","Unchanged for any speed"],"correct_index":2,"explanation":"Approaching motion compresses the wavefront spacing at the observer, increasing observed frequency. This is the Doppler effect.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"For N₂(g)+3H₂(g) ⇌ 2NH₃(g), what does increasing pressure by reducing volume favour at constant temperature?","options":["The reverse reaction, with fewer gas moles","Neither direction because gas amounts are equal","Only removal of the catalyst","The forward reaction, with fewer gas moles"],"correct_index":3,"explanation":"There are 4 stoichiometric moles of gas on the left and 2 on the right. Compression favours the side with fewer gas moles.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"What does a catalyst change in a reaction at equilibrium?","options":["The rates of both forward and reverse reactions, not the equilibrium constant at fixed temperature","The equilibrium constant at unchanged temperature","Only the forward rate","The final equilibrium composition by itself"],"correct_index":0,"explanation":"A catalyst offers a lower-activation-energy pathway for both directions. Equilibrium is reached faster without shifting its position at the same temperature.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"A catalyst is added to a sealed system already at equilibrium at constant temperature. A learner predicts a larger final product yield. Which evaluation is valid?","options":["Only the forward reaction speeds up, increasing final yield.","The catalyst changes the equilibrium constant at this temperature.","The catalyst speeds both directions but does not change the equilibrium composition.","All reactions stop once the catalyst is added."],"correct_index":2,"explanation":"A catalyst provides lower-activation-energy pathways in both directions. At fixed temperature it does not alter the equilibrium constant or equilibrium yield; it affects the approach to equilibrium.","cognitive_level":{"code":"L4","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Work, Doppler effect and equilibrium. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","phsc"],"metadata":{"term":2,"focus":"Work, Doppler effect and equilibrium","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=DXUcPsguELw%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Recall","Comprehension","Analysis and application","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"b1fd2dd1-8628-5c7e-b244-69f6b3cf54d3","title":"Physical Sciences · Grade 12 · Term 3: Electric circuits, photoelectric effect and cells · Set A","subject":"Physical Sciences","grade":"Grade 12","questions":[{"question":"A cell has emf 12 V and internal resistance 1 Ω. It supplies 2 A. Find its terminal potential difference.","options":["14 V","12 V","10 V","6 V"],"correct_index":2,"explanation":"V=ε−Ir=12−2×1=10 V while supplying current. The internal resistor accounts for the lost volts.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"In a galvanic cell, oxidation occurs at the…","options":["Cathode","Salt bridge only","Voltmeter","Anode"],"correct_index":3,"explanation":"Oxidation always occurs at the anode and reduction at the cathode. In a galvanic cell, electrons flow externally from anode to cathode.","cognitive_level":{"code":"L1","label":"Recall","band":"lower"}},{"question":"Light below a metal's threshold frequency shines on it. Increasing intensity alone will…","options":["Not cause photoemission in the standard single-photon model","Always eject electrons immediately","Increase each photon's frequency","Reduce the metal's work function to zero"],"correct_index":0,"explanation":"Each photon's energy is hf. Below threshold, individual photons lack enough energy to eject electrons; greater intensity does not raise their frequency.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"A generator converts predominantly which energy into electrical energy?","options":["Electrical energy into chemical energy","Mechanical energy","Nuclear energy directly with no process","Sound energy only"],"correct_index":1,"explanation":"Relative motion in a magnetic field induces emf. Mechanical input drives the generator, transferring energy to the electrical circuit.","cognitive_level":{"code":"L1","label":"Recall","band":"lower"}},{"question":"A metal emits no electrons under light below its threshold frequency. Which experiment best distinguishes the photon model from an intensity-only explanation?","options":["Change metal, frequency and intensity together with no record.","Count electrons once without measuring the light.","Keep frequency below threshold and increase intensity; then raise frequency above threshold.","Assume all bright light must eject electrons."],"correct_index":2,"explanation":"Below threshold, extra intensity alone does not cause standard single-photon emission. Crossing the frequency threshold tests the photon-energy condition while staged changes avoid confounding variables.","cognitive_level":{"code":"L4","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Electric circuits, photoelectric effect and cells. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","phsc"],"metadata":{"term":3,"focus":"Electric circuits, photoelectric effect and cells","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=DXUcPsguELw%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Recall","Comprehension","Analysis and application","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"f3684dee-3627-5332-8be2-b5693d7a8f57","title":"Physical Sciences · Grade 12 · Term 4: Physics and chemistry examination revision · Set A","subject":"Physical Sciences","grade":"Grade 12","questions":[{"question":"A 2 kg trolley changes velocity from 1 to 4 m·s⁻¹ east. Find the change in momentum.","options":["8 kg·m·s⁻¹ east","2 kg·m·s⁻¹ east","10 kg·m·s⁻¹ east","6 kg·m·s⁻¹ east"],"correct_index":3,"explanation":"Δp=m(v−u)=2(4−1)=6 kg·m·s⁻¹ east. Final momentum alone is 8, not the change.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"Find the pH of a strong monoprotic acid with [H₃O⁺] = 1 × 10⁻³ mol·dm⁻³.","options":["3","−3","11","0.001"],"correct_index":0,"explanation":"pH=−log₁₀[H₃O⁺]=−log₁₀(10⁻³)=3. The minus sign reverses the exponent's sign.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"For an exothermic forward reaction, increasing temperature shifts equilibrium towards…","options":["Products","Reactants","Both sides equally in composition","The catalyst"],"correct_index":1,"explanation":"Heat is effectively a product in an exothermic reaction. Increasing temperature favours the endothermic reverse reaction, increasing the proportion of reactants.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"A metal has work function 3 eV; incident photons have energy 5 eV. Find the maximum photoelectron kinetic energy.","options":["8 eV","15 eV","2 eV","3 eV"],"correct_index":2,"explanation":"Einstein's equation gives Kₘₐₓ=E(photon)−W₀=5−3=2 eV. Some photon energy frees the electron before any appears as kinetic energy.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"A trolley's momentum changes by 6 kg·m·s⁻¹. Two bumpers produce this same change in 0.1 s and 0.3 s. Which safety argument is justified?","options":["The 0.3 s bumper gives three times the average net force.","Both average forces must be equal because impulse is equal.","The 0.3 s bumper gives one third of the average net force.","Longer stopping time must increase the momentum change."],"correct_index":2,"explanation":"Average net force is impulse divided by contact time. The same 6 N·s gives 60 N over 0.1 s and 20 N over 0.3 s; longer time lowers the average force.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Physics and chemistry examination revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","phsc"],"metadata":{"term":4,"focus":"Physics and chemistry examination revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=DXUcPsguELw%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Recall","Comprehension","Analysis and application","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"181e9932-02f8-5b72-a097-932d88c315cb","title":"Life Sciences · Grade 12 · Term 2: Inheritance and human responses · Set A","subject":"Life Sciences","grade":"Grade 12","questions":[{"question":"In a monohybrid cross Aa × Aa with complete dominance, P(aa) is…","options":["1/2","3/4","1/4","1"],"correct_index":2,"explanation":"The four equally likely combinations are AA, Aa, Aa and aa. Only one is homozygous recessive.","cognitive_level":{"code":"L3","label":"Applying scientific knowledge","band":"middle"}},{"question":"What connects a sensory receptor to the central nervous system in a simple reflex pathway?","options":["Motor neuron","Effector muscle","Endocrine gland only","Sensory neuron"],"correct_index":3,"explanation":"A sensory neuron carries impulses from a receptor towards the CNS. A motor neuron carries impulses from the CNS to an effector.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"Why is insulin release after a meal an example of negative feedback?","options":["It helps bring raised blood glucose back towards its normal range","It keeps increasing blood glucose without limit","It destroys all glucose permanently","It prevents glucose uptake by all cells"],"correct_index":0,"explanation":"Raised blood glucose stimulates insulin release. Its effects reduce blood glucose, opposing the original change.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"A shoot bends towards light. What is this response called?","options":["Negative phototropism","Positive phototropism","Positive geotropism only","Transpiration"],"correct_index":1,"explanation":"Phototropism is growth in response to directional light. Growth towards the stimulus is positive; differential growth causes the bending.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"Two parents with a dominant phenotype have a child with a recessive phenotype for a simple complete-dominance trait. What follows, assuming the model applies?","options":["One recessive child means all later children must be recessive.","Neither parent can carry a recessive allele.","Both parents must carry the recessive allele, but the next child's phenotype is not fixed.","The next child must be dominant to balance the ratio."],"correct_index":2,"explanation":"A recessive child is aa, requiring an a allele from each parent. Dominant parents must therefore both be Aa; each new conception has its own 1/4 probability of aa.","cognitive_level":{"code":"L3","label":"Applying scientific knowledge","band":"middle"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Inheritance and human responses. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","lisc"],"metadata":{"term":2,"focus":"Inheritance and human responses","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=c5UFxlh6dx4%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing science","Understanding science","Applying scientific knowledge","Evaluating, analysing and synthesising"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"b6696505-6ade-54a3-a39b-af92585b3087","title":"Life Sciences · Grade 12 · Term 3: Evolution and interpreting evidence · Set A","subject":"Life Sciences","grade":"Grade 12","questions":[{"question":"A population has inherited variation in beak size. A food change favours larger beaks. What explains larger beaks becoming more common over generations?","options":["Every bird consciously enlarges its beak","The environment directly rewrites every bird's genes in the same way","Individuals evolve because they need to survive","Individuals with advantageous inherited traits leave more surviving offspring"],"correct_index":3,"explanation":"Natural selection acts on existing heritable variation. Changes in reproductive success alter trait frequencies across generations, not by individual intention.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"What is required for populations to become separate species through reproductive isolation?","options":["They cease exchanging genes and diverge sufficiently","They must become identical in every feature","They must live on different planets","Every isolated individual must die"],"correct_index":0,"explanation":"Restricted gene flow allows divergence. Speciation involves reproductive isolation, not simply living far apart for a short time.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"How do homologous structures support common ancestry?","options":["They must perform identical functions","They share an underlying structural pattern despite possible differences in function","They prove organisms are the same species","They arise only from identical environments"],"correct_index":1,"explanation":"Shared underlying structure is consistent with descent from a common ancestor, modified for different uses. Similar function alone can instead reflect analogy.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"Which finding supports an African origin of modern humans?","options":["The claim that living humans belong to separate biological races ranked by ability","The claim that evolution stopped outside Africa","Fossil and genetic evidence consistent with early modern humans in Africa and later dispersal","The absence of all fossils outside Africa"],"correct_index":2,"explanation":"The Out-of-Africa model is supported by multiple lines of fossil and genetic evidence. It does not rank living populations or deny later migration and interbreeding.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"After drought, large-beaked birds become more common. Which additional evidence best supports natural selection rather than a temporary change within individuals?","options":["Each bird reports trying harder to grow a beak.","Only the population's location is recorded.","Beak-size variation is inherited and larger-beaked birds leave more surviving offspring.","A single adult changes its posture for a photograph."],"correct_index":2,"explanation":"Natural selection requires heritable variation and differential reproductive success. A change in frequency alone needs evidence linking the trait to inheritance and survival or reproduction.","cognitive_level":{"code":"L4","label":"Evaluating, analysing and synthesising","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Evolution and interpreting evidence. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","lisc"],"metadata":{"term":3,"focus":"Evolution and interpreting evidence","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=c5UFxlh6dx4%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing science","Understanding science","Applying scientific knowledge","Evaluating, analysing and synthesising"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"f86627b3-b5bb-50b0-ac25-416cd3a65868","title":"Life Sciences · Grade 12 · Term 4: Integrated biological reasoning revision · Set A","subject":"Life Sciences","grade":"Grade 12","questions":[{"question":"DNA has 20% adenine in a double-stranded molecule. Approximately what percentage is guanine?","options":["30%","20%","40%","60%"],"correct_index":0,"explanation":"A pairs with T, so T is 20%. The remaining 60% is G+C, split equally: G=30%.","cognitive_level":{"code":"L3","label":"Applying scientific knowledge","band":"middle"}},{"question":"Why does meiosis contribute to variation?","options":["It produces only genetically identical gametes","Crossing over and independent assortment produce different allele combinations","It doubles chromosome number in each gamete","It eliminates all mutations"],"correct_index":1,"explanation":"Crossing over and independent chromosome assortment create different combinations. Meiosis also halves chromosome number for sexual reproduction.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"A healthy person becomes dehydrated. Which response helps conserve water?","options":["Decreased ADH and unlimited water loss","Kidneys stop responding to hormones permanently","Increased ADH and increased kidney water reabsorption","More dilute urine in every circumstance"],"correct_index":2,"explanation":"Dehydration generally stimulates ADH release, promoting water reabsorption and smaller volumes of concentrated urine.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"A farmer claims pesticide resistance appears because insects try harder to survive. Which correction is best?","options":["All insects choose new genes on exposure","Pesticide makes every insect equally resistant immediately","Resistance cannot be inherited","Inherited resistant variants survive and reproduce more successfully under pesticide selection"],"correct_index":3,"explanation":"Selection favours existing resistant variants or variants arising through mutation. Their descendants become more common; effort does not direct genetic change.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"A pesticide kills 95% of insects. Survivors produce offspring that also resist it. What control-study evidence would strengthen an inherited-resistance explanation?","options":["Every survivor is assumed to have chosen resistance.","Only the pesticide bottle's colour is recorded.","Resistance persists in offspring raised without pesticide and differs from a susceptible comparison line.","No offspring are tested because survival proves inheritance."],"correct_index":2,"explanation":"Raising offspring without exposure helps distinguish inherited resistance from an immediate environmental response. A susceptible comparison and repeated trials strengthen the interpretation.","cognitive_level":{"code":"L4","label":"Evaluating, analysing and synthesising","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Integrated biological reasoning revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","lisc"],"metadata":{"term":4,"focus":"Integrated biological reasoning revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=c5UFxlh6dx4%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing science","Understanding science","Applying scientific knowledge","Evaluating, analysing and synthesising"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"a988b912-384c-5ac5-816b-2cbbf1f5bf0e","title":"Accounting · Grade 12 · Term 2: Inventory, assets and cost accounting · Set A","subject":"Accounting","grade":"Grade 12","questions":[{"question":"A FIFO system has 10 units at R20, followed by 10 at R30. Twelve units are sold. Find cost of sales.","options":["R300","R340","R360","R260"],"correct_index":3,"explanation":"FIFO issues the oldest units first: 10×20 + 2×30 = R260. The remaining eight units are from the R30 batch.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Fixed costs are R120 000 and contribution is R40 per unit. Find break-even units.","options":["3 000","4 800 000","4 000","480"],"correct_index":0,"explanation":"Break-even units = fixed costs/contribution per unit = 120 000/40 = 3 000. Contribution is selling price less variable cost.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"An asset costs R100 000; accumulated depreciation is R35 000. Find its carrying value.","options":["R135 000","R65 000","R35 000","R100 000"],"correct_index":1,"explanation":"Carrying value = cost−accumulated depreciation = R65 000. It need not equal the asset's market value.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why separate asset custody from record keeping where practical?","options":["To guarantee fraud is impossible","To avoid all asset registers","To reduce the risk of undetected error or fraud","To make records confidential from auditors"],"correct_index":2,"explanation":"Segregation of duties makes unauthorised actions harder to conceal. It reduces risk but requires checks and does not eliminate every risk.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Two inventory methods give different profits during rising purchase prices, with identical sales and physical stock. What should an analyst check first?","options":["Which method changes the actual number of units sold.","Whether a higher accounting profit guarantees more cash.","The valuation method and its effect on cost of sales and closing inventory.","Whether stock costing can replace a physical count."],"correct_index":2,"explanation":"Different cost-flow assumptions can allocate different purchase costs to sales and closing inventory. Understand the method before comparing profits; it does not itself change physical units or cash already paid.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Inventory, assets and cost accounting. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","acc"],"metadata":{"term":2,"focus":"Inventory, assets and cost accounting","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=g4DcPbejtts%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"5fa0f8ab-586b-52ec-aedc-c09b4af6c733","title":"Accounting · Grade 12 · Term 3: VAT and forward-looking budgets · Set A","subject":"Accounting","grade":"Grade 12","questions":[{"question":"For this exercise output VAT is R18 000 and deductible input VAT R11 000. What is payable?","options":["R7 000","R29 000","R11 000","R18 000"],"correct_index":0,"explanation":"Net VAT payable = output−deductible input = 18 000−11 000 = R7 000, assuming no other adjustments.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why does depreciation appear in a projected income statement but not as a cash-budget payment?","options":["It is always income","It is an expense without a current cash outflow","It is illegal in all budgets","It is paid to the bank every month"],"correct_index":1,"explanation":"The income statement forecasts profit using accrual expenses; a cash budget forecasts cash movements. Depreciation reduces profit without a cash payment in that period.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Credit sales are R50 000. The collection policy expects 80% next month, with no discount. Find next month's receipt from these sales.","options":["R10 000","R50 000","R40 000","R62 500"],"correct_index":2,"explanation":"Expected cash collection = 50 000×0.80 = R40 000. Record receipts in the month collected, not automatically when sold.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A budget forecast shows a cash shortfall next month. Which response is most useful?","options":["Ignore it until every supplier is overdue","Treat the forecast as a guaranteed bank balance","Record an imaginary cash receipt","Investigate timing, reduce avoidable payments and plan funding early"],"correct_index":3,"explanation":"A cash forecast is an early warning. Review assumptions and practical actions; fabricating receipts hides rather than solves the problem.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A profitable business forecasts a cash deficit because customers pay after supplier debts fall due. Which recommendation addresses the cause?","options":["Increase depreciation to generate immediate cash.","Ignore the deficit because profit guarantees positive bank funds.","Negotiate payment timing and improve collections while assessing suitable short-term funding.","Record unpaid customer invoices as cash already received."],"correct_index":2,"explanation":"The problem is the timing gap between receipts and payments. A cash forecast, collection action and negotiated terms address it; accrual profit and non-cash adjustments cannot guarantee immediate liquidity.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: VAT and forward-looking budgets. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","acc"],"metadata":{"term":3,"focus":"VAT and forward-looking budgets","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=g4DcPbejtts%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"e53221f6-720c-5bb0-b770-5d7fef68ef48","title":"Accounting · Grade 12 · Term 4: Integrated financial and control revision · Set A","subject":"Accounting","grade":"Grade 12","questions":[{"question":"Net profit after tax is R240 000 and average shareholders' equity R1 200 000. Find the return on average equity.","options":["5%","20%","50%","200%"],"correct_index":1,"explanation":"Return = profit after tax/average equity×100 = 240 000/1 200 000×100=20%. Use the average equity specified.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A company has current assets R300 000 and liabilities due within a year R200 000. Find the current ratio.","options":["0.67:1","3:1","1.5:1","2:1"],"correct_index":2,"explanation":"Current ratio = current assets/current liabilities = 300 000/200 000=1.5:1. Assess stock quality and collection timing as well.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why should a bank reconciliation investigate unexplained differences?","options":["All differences are automatically bank fraud","Reconciliation changes the bank's actual cash without evidence","A bank statement never contains errors","They may reveal recording errors, timing differences or unauthorised transactions"],"correct_index":3,"explanation":"Reconciliation compares independent records. Identify and substantiate each difference before recording any necessary correction.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A company repays R40 000 of a loan using bank funds. What happens to total assets and liabilities?","options":["Both decrease by R40 000","Both increase by R40 000","Assets increase and liabilities decrease","Equity increases by R40 000"],"correct_index":0,"explanation":"Bank, an asset, decreases and the loan liability decreases by the same amount. Repaying principal is not itself an expense.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A business repays a R40 000 loan and its current ratio worsens. A director calls the repayment an expense that reduced profit. Which evaluation is sound?","options":["Principal repayment always reduces profit by R40 000.","Loan repayment creates R40 000 revenue.","Loan principal reduces cash and liabilities; assess liquidity separately from interest expense.","A lower current ratio necessarily proves fraud."],"correct_index":2,"explanation":"Repayment of principal reduces an asset and a liability, rather than being an operating expense. Interest is accounted for separately; the remaining cash and liability classification affect liquidity analysis.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Integrated financial and control revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","acc"],"metadata":{"term":4,"focus":"Integrated financial and control revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=g4DcPbejtts%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}}]$smartbridge$::jsonb)
